int grade(int s, int a) {
    int r = 0;
    if (s >= 90) r = 4;
    else if (s >= 80) r = 3;
    else if (s >= 70) r = 2;
    else r = 1;
    if (a < 3 && r > 1) r++;
    return r;
}

int count(int a[], int n) {
    int c = 0;
    for (int i = 0; i < n; i++) {
        if (a[i] < 0) continue;
        if (a[i] % 2 == 0 || a[i] > 100) c++;
    }
    while (c > 10) c -= 10;
    return c;
}

int fee(int t, int w) {
    int f;
    switch (t) {
        case 1: f = 10; break;
        case 2: f = 20; break;
        case 3: f = 30; break;
        default: f = 0;
    }
    if (w > 5) f += 5;
    return f;
}

int pairs(int a[], int n, int k) {
    int c = 0;
    for (int i = 0; i < n; i++)
        for (int j = i + 1; j < n; j++)
            if (a[i] + a[j] == k) c++;
    return c;
}

int steps(int x) {
    int s = 0;
    while (x != 1) {
        x = (x % 2 == 0) ? x / 2 : 3 * x + 1;
        s++;
        if (s > 1000) break;
    }
    return s;
}

int valid(int a, int b, int c) {
    if (a > 0 && b > 0 && c > 0) {
        if (a + b > c || b + c > a || a + c > b)
            return 1;
    }
    return 0;
}

int classify(int t, int h) {
    int r = 0;
    while (t > 0) {
        if (t > 30 && h > 70) r += 2;
        else if (t > 30 || h > 70) r += 1;
        t -= 10;
    }
    return r;
}

